import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const files = {"api-server/src/routes/admin-ui-layouts.ts": "", "api-server/src/routes/ui-layouts.ts": "", "supabase/migrations/20260728_admin_ui_layouts.sql": "", "stock-analyzer/src/lib/ui-layout.ts": "와", "stock-analyzer/src/pages/admin-ui-builder.tsx": ""};

async function writeBase64(path, encoded) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, Buffer.from(encoded, 'base64').toString('utf8'), 'utf8');
  console.log(`작성: ${path}`);
}

function replaceOnce(source, before, after, label) {
  const count = source.split(before).length - 1;
  if (count !== 1) {
    throw new Error(`${label} 위치를 찾지 못했습니다. 발견 횟수: ${count}`);
  }
  return source.replace(before, after);
}

for (const [path, encoded] of Object.entries(files)) {
  await writeBase64(path, encoded);
}

